// Gather leads from OpenStreetMap. Geocode the city (Nominatim) -> bounding box,
// then query Overpass by bbox. Both calls go through n8n's own HTTP helper, so we
// control the exact request (the built-in HTTP node was getting 406'd by Overpass).
const body = $json.body || $json;
const raw = String(body.text || '');
const text = raw.toLowerCase();
const TAGS = [[/dentist|dental/, 'amenity=dentist'],[/cafe|coffee/, 'amenity=cafe'],[/restaurant|dining/, 'amenity=restaurant'],[/gym|fitness/, 'leisure=fitness_centre'],[/salon|beauty|barber/, 'shop=beauty'],[/hotel/, 'tourism=hotel'],[/clinic|hospital/, 'amenity=clinic']];
let tag = 'shop';
for (const [re, t] of TAGS) { if (re.test(text)) { tag = t; break; } }
const m = raw.match(/\bin\s+(.+)$/i);
const city = (m ? m[1] : (body.region || '')).trim();
const [k, v] = tag.includes('=') ? tag.split('=') : [tag, null];
const sel = v ? `["${k}"="${v}"]` : `["${k}"]`;
const UA = 'nyx-automate-leads/1.0';
let elements = [];
if (city) {
  const geo = await this.helpers.httpRequest({ method: 'GET', url: 'https://nominatim.openstreetmap.org/search', qs: { q: city, format: 'json', limit: 1 }, headers: { 'User-Agent': UA }, json: true });
  const bb = Array.isArray(geo) && geo[0] && geo[0].boundingbox;
  if (bb) {
    const [s, n, w, e] = bb;
    const ql = `[out:json][timeout:25];(node${sel}(${s},${w},${n},${e});way${sel}(${s},${w},${n},${e}););out center 50;`;
    const ov = await this.helpers.httpRequest({ method: 'GET', url: 'https://overpass-api.de/api/interpreter', qs: { data: ql }, headers: { 'User-Agent': UA, 'Accept': 'application/json' }, json: true });
    elements = (ov && ov.elements) || [];
  }
}
return [{ json: { elements, runId: body.runId || null, queryId: body.queryId || null } }];

// Map Overpass elements -> normalized leads.
const els = ($json.elements || []);
const leads = [];
for (const e of els) {
  const t = e.tags || {};
  if (!t.name) continue;
  const addr = [t['addr:housenumber'], t['addr:street'], t['addr:city']].filter(Boolean).join(', ');
  leads.push({
    source: 'openstreetmap',
    sourceId: `${e.type}/${e.id}`,
    name: t.name,
    website: t.website || t['contact:website'] || undefined,
    phone: t.phone || t['contact:phone'] || undefined,
    instagram: t['contact:instagram'] || undefined,
    address: addr || undefined,
    category: t.amenity || t.shop || t.tourism || t.leisure || undefined,
  });
}
return [{ json: { runId: $json.runId, queryId: $json.queryId, leads } }];
// TODO (own it): add Split-in-Batches + HTTP to visit each lead.website and
// extract the Instagram link / email before ingest (see n8n/README.md).
